  documentoClienteId: number | null;
  movimientoOrigenId: number | null;
  usuarioId: number;
  justificacion: string | null;
  revisado: boolean;
  revisadoPor: number | null;
  revisadoAt: string | null;
  uuidCliente: string | null;
